css:
#nat-hero-slider {
  border-radius: 0.75rem;
  overflow: hidden;
  box-shadow: 0 0.5rem 1rem rgba(0,0,0,0.1);
  margin-bottom: 2rem;
}
.nat-slide-img {
  height: 450px;
  width: 100%;
  object-fit: cover;
}
.nat-slide-overlay {
  position: absolute;
  top: 0; left: 0; width: 100%; height: 100%;
  background: linear-gradient(to bottom, rgba(0,0,0,0.1) 40%, rgba(0,0,0,0.8) 100%);
}
.nat-carousel-caption {
  position: absolute;
  bottom: 2rem;
  left: 5%;
  right: 5%;
  text-align: center;
  z-index: 10;
}
.nat-carousel-caption h3 {
  font-size: 2rem;
  font-weight: 800;
  text-shadow: 1px 1px 4px rgba(0,0,0,0.6);
  margin-bottom: 1rem;
  color: #ffffff;
}
@media (max-width: 768px) {
  .nat-slide-img { height: 300px; }
  .nat-carousel-caption h3 { font-size: 1.35rem; }
  .nat-carousel-caption { bottom: 1rem; }
}

javascript:
(function() {
  document.addEventListener('DOMContentLoaded', function() {
    const feedUrl = '/feeds/posts/default?alt=json&max-results=3';
    fetch(feedUrl)
      .then(r => r.json())
      .then(data => {
        const entries = data.feed.entry || [];
        let innerHtml = '';
        let indicatorsHtml = '';

        if (entries.length > 0) {
          entries.forEach((entry, index) => {
            const title = entry.title.$t;
            let link = '';
            entry.link.forEach(l => { if (l.rel === 'alternate') link = l.href; });

            let imgUrl = entry.media$thumbnail
              ? entry.media$thumbnail.url
              : 'https://placehold.co/1200x500';
            imgUrl = imgUrl.replace(/\/s[0-9]+(-c)?\//g, '/w1200-h500-c/');

            const activeClass = index === 0 ? 'active' : '';
            const ariaCurrent = index === 0 ? 'true' : 'false';

            indicatorsHtml += `<button type="button" data-bs-target="#nat-hero-slider" data-bs-slide-to="${index}" class="${activeClass}" aria-current="${ariaCurrent}" aria-label="Slide ${index + 1}"></button>`;

            innerHtml += `
              <div class="carousel-item ${activeClass}">
                <img src="${imgUrl}" class="d-block nat-slide-img" alt="${title}">
                <div class="nat-slide-overlay"></div>
                <div class="nat-carousel-caption">
                  <h3>${title}</h3>
                  <a href="${link}" class="btn btn-primary rounded-pill px-4 fw-bold"
                     style="background-color: var(--nat-primary, #8FBC8F); border: none; color: #121212;">
                    Ler Artigo
                  </a>
                </div>
              </div>`;
          });

          document.getElementById('slider-indicators').innerHTML = indicatorsHtml;
          document.getElementById('slider-inner').innerHTML = innerHtml;
        }
      })
      .catch(err => {
        console.error('Slider erro:', err);
        const el = document.getElementById('nat-hero-slider');
        if (el) el.style.display = 'none';
      });
  });
})();
